{"cmd":"python3 - <<'PY'
import pdfplumber, re, pandas as pd, json

pdf_path = '/root/employees_backup.pdf'
excel_path = '/root/employees_current.xlsx'

cols = ['ID','First','Last','Dept','Position','Salary','Years','Location','Score']
rows=[]
pattern = re.compile(r'^EMP\d{5}$')
with pdfplumber.open(pdf_path) as pdf:
    for page in pdf.pages:
        tables = page.extract_tables()
        for table in tables:
            for row in table:
                if not row:
                    continue
                cells=[c.strip() if isinstance(c,str) else c for c in row]
                if all((c is None or str(c).strip()=='' ) for c in cells):
                    continue
                if cells[0]=='ID' and 'First' in cells:
                    continue
                if isinstance(cells[0], str) and pattern.match(cells[0]):
                    if len(cells) >= 9:
                        rows.append(cells[:9])
                    else:
                        # skip malformed rows
                        pass

old_df = pd.DataFrame(rows, columns=cols)

# Clean types
for col in ['First','Last','Dept','Position','Location']:
    old_df[col] = old_df[col].astype(str).str.strip()

old_df['Salary'] = old_df['Salary'].astype(str).str.replace(',', '', regex=False)
old_df['Salary'] = pd.to_numeric(old_df['Salary'], errors='coerce')
old_df['Years'] = pd.to_numeric(old_df['Years'], errors='coerce')
old_df['Score'] = pd.to_numeric(old_df['Score'], errors='coerce')

# Read new
new_df = pd.read_excel(excel_path, engine='openpyxl')
new_df = new_df.rename(columns=lambda c: str(c).strip())

for col in ['First','Last','Dept','Position','Location']:
    if col in new_df.columns:
        new_df[col] = new_df[col].astype(str).str.strip()

for col in ['Salary','Years','Score']:
    if col in new_df.columns:
        new_df[col] = pd.to_numeric(new_df[col], errors='coerce')

# set index
old_idx = old_df.set_index('ID')
new_idx = new_df.set_index('ID')

old_ids = set(old_idx.index)
new_ids = set(new_idx.index)

deleted = sorted(old_ids - new_ids)

common = sorted(old_ids & new_ids)

modified = []
for emp_id in common:
    old_row = old_idx.loc[emp_id]
    new_row = new_idx.loc[emp_id]
    for col in cols[1:]:
        old_val = old_row[col]
        new_val = new_row[col]
        # treat NaN
        if pd.isna(old_val) and pd.isna(new_val):
            continue
        if pd.isna(old_val) != pd.isna(new_val):
            changed = True
        else:
            changed = old_val != new_val
        if changed:
            # convert numpy types to python
            if pd.isna(old_val):
                old_val = None
            if pd.isna(new_val):
                new_val = None
            # ensure python types
            if hasattr(old_val, 'item'):
                old_val = old_val.item()
            if hasattr(new_val, 'item'):
                new_val = new_val.item()
            modified.append({
                'id': emp_id,
                'field': col,
                'old_value': old_val,
                'new_value': new_val,
            })

# sort modified by id then field
modified.sort(key=lambda x: (x['id'], x['field']))

report = {
    'deleted_employees': deleted,
    'modified_employees': modified,
}

out_path = '/root/diff_report.json'
with open(out_path, 'w', encoding='utf-8') as f:
    json.dump(report, f, indent=2)

print('deleted', len(deleted))
print('modified', len(modified))
print('out', out_path)
# show sample
print('first deleted', deleted[:5])
print('first modified', modified[:3])
PY"}

